# Security Review: app.js

## Current State Analysis

The current `app.js` is a minimal Express application with significant security shortcomings:

### Current Issues:
1. **No middleware for security headers**
2. **No rate limiting**
3. **No input validation**
4. **No error handling middleware**
5. **No logging**
6. **No body parser configuration**
7. **No CORS configuration**
8. **No request size limits**
9. **Information leakage in error messages**
10. **No helmet for HTTP headers**

---

## Recommended Improvements

### 1. Security Headers (Helmet)

**Issue:** Missing security-related HTTP headers
**Risk:** XSS, clickjacking, MIME-sniffing attacks

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 2. Rate Limiting

**Issue:** No protection against brute force or DDoS attacks
**Risk:** Service exhaustion, credential stuffing

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
```

### 3. Input Validation

**Issue:** No validation of query parameters, request body, or path parameters
**Risk:** SQL injection, NoSQL injection, XSS, parameter pollution

**Solution:**
```javascript
const { body, query, param, validationResult } = require('express-validator');

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// Sanitize inputs
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 4. Error Handling Middleware

**Issue:** No centralized error handling
**Risk:** Information leakage, inconsistent error responses

**Solution:**
```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource was not found' 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (don't expose to client)
  console.error('Error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});
```

### 5. CORS Configuration

**Issue:** No CORS restrictions
**Risk:** Cross-origin attacks, data theft

**Solution:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  optionsSuccessStatus: 204
};

app.use(cors(corsOptions));
```

### 6. Request Timeout

**Issue:** No timeout on requests
**Risk:** Slowloris attacks, resource exhaustion

**Solution:**
```javascript
const timeout = require('connect-timeout');
app.use(timeout('30s'));

app.use((req, res, next) => {
  if (!req.timedout) next();
});
```

### 7. Safe JSON Parsing

**Issue:** Potential prototype pollution from JSON parsing
**Risk:** Remote code execution

**Solution:**
```javascript
app.use(express.json({
  limit: '10kb',
  strict: true
}));
```

### 8. HTTP Parameter Pollution Protection

**Issue:** Vulnerable to parameter pollution
**Risk:** Authentication bypass, logic bypass

**Solution:**
```javascript
const hpp = require('hpp');
app.use(hpp());
```

### 9. Logging and Monitoring

**Issue:** No request logging or security event tracking
**Risk:** Unable to detect or investigate attacks

**Solution:**
```javascript
const morgan = require('morgan');
const rfs = require('rotating-file-stream');

// Create a rotating write stream
const accessLogStream = rfs.createStream('access.log', {
  interval: '1d',
  path: __dirname + '/log'
});

// Setup logger
app.use(morgan('combined', { stream: accessLogStream }));
```

### 10. Environment Configuration

**Issue:** Hardcoded values, no environment-based config
**Risk:** Credential exposure, lack of flexibility

**Solution:**
```javascript
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',
  rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW) || 900000,
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,
};
```

---

## Complete Secure Implementation

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const hpp = require('hpp');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
};

app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW) || 900000,
  max: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// HTTP Parameter Pollution protection
app.use(hpp());

// Body parser with size limits
app.use(express.json({ limit: '10kb', strict: true }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with validation
app.get('/users', 
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
    query('sort').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field')
  ],
  validate,
  (req, res) => {
    const { limit = 10, offset = 0, sort = 'id' } = req.query;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination and sorting
    const startIndex = parseInt(offset);
    const endIndex = startIndex + parseInt(limit);
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
      }
    });
  }
);

// User by ID endpoint with validation
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
  ],
  validate,
  (req, res) => {
    const { id } = req.params;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource was not found' 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Only start server if not in test mode
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;
```

---

## Additional Security Recommendations

### 1. Dependencies
Add these packages to `package.json`:
```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "cors": "^2.8.5",
    "hpp": "^0.2.3",
    "express-validator": "^7.0.1",
    "morgan": "^1.10.0",
    "dotenv": "^16.3.1"
  }
}
```

### 2. Environment Variables (.env.example)
```
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
RATE_LIMIT_WINDOW=900000
RATE_LIMIT_MAX=100
```

### 3. Security Checklist

- [ ] Implement all security middleware
- [ ] Add input validation to all endpoints
- [ ] Set up proper error handling
- [ ] Configure CORS appropriately
- [ ] Implement rate limiting
- [ ] Add request logging
- [ ] Set up environment variables
- [ ] Disable stack traces in production
- [ ] Keep dependencies updated
- [ ] Run security audits (`npm audit`)
- [ ] Implement authentication/authorization if needed
- [ ] Add HTTPS in production
- [ ] Set up monitoring and alerting

### 4. Testing

Add security tests using tools like:
- `npm audit` for vulnerability scanning
- Jest/Jest-cucumber for security unit tests
- OWASP ZAP or Burp Suite for penetration testing
- Supertest for API security testing

---

## Priority Recommendations (In Order)

1. **HIGH PRIORITY:** Add helmet middleware
2. **HIGH PRIORITY:** Implement rate limiting
3. **HIGH PRIORITY:** Add error handling middleware
4. **MEDIUM PRIORITY:** Add input validation
5. **MEDIUM PRIORITY:** Configure CORS
6. **MEDIUM PRIORITY:** Add request size limits
7. **LOW PRIORITY:** Implement logging
8. **LOW PRIORITY:** Add monitoring

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet Documentation](https://helmetjs.github.io/)
- [Node.js Security Checklist](https://github.com/lirantal/nodejs-security-checklist)

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const hpp = require('hpp');
const { body, query, param, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS - Configure Cross-Origin Resource Sharing
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 204
};

app.use(cors(corsOptions));

// 3. Rate Limiting - Prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW) || 15 * 60 * 1000, // 15 minutes
  max: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  message: {
    error: 'Too many requests',
    message: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: Math.round(parseInt(process.env.RATE_LIMIT_WINDOW || 900000) / 1000)
    });
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for authentication endpoints (when added)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts, please try again later.'
});

// 4. HTTP Parameter Pollution protection
app.use(hpp({
  whitelist: ['sort', 'fields'], // Allow parameters that can have multiple values
}));

// 5. Body parser with security settings
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  strict: true,  // Only accept objects and arrays
  type: 'application/json'
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 100
}));

// 6. Request logging
if (process.env.NODE_ENV !== 'test') {
  const logFormat = process.env.NODE_ENV === 'production' 
    ? 'combined' 
    : ':method :url :status :response-time ms - :res[content-length]';

  app.use(morgan(logFormat));
}

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Generic validation error handler
const validate = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', {
      url: req.url,
      method: req.method,
      ip: req.ip,
      errors: errors.array()
    });

    return res.status(400).json({ 
      error: 'Validation failed',
      message: 'The request contains invalid data.',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }

  next();
};

// Sanitize user input to prevent XSS
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    // Basic sanitization - in production, use a library like dompurify
    const sanitizeObject = (obj) => {
      if (typeof obj !== 'object' || obj === null) return obj;

      const sanitized = {};
      for (const key in obj) {
        if (typeof obj[key] === 'string') {
          // Remove potentially dangerous characters
          sanitized[key] = obj[key]
            .replace(/[<>]/g, '') // Remove < and >
            .trim();
        } else if (typeof obj[key] === 'object') {
          sanitized[key] = sanitizeObject(obj[key]);
        } else {
          sanitized[key] = obj[key];
        }
      }
      return sanitized;
    };

    req.body = sanitizeObject(req.body);
  }
  next();
};

app.use(sanitizeInput);

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    version: process.env.npm_package_version || '1.0.0'
  });
});

/**
 * Get all users with pagination and filtering
 * GET /users?limit=10&offset=0&sort=id
 */
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer or zero')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email')
      .trim(),
    query('search')
      .optional()
      .isLength({ max: 100 })
      .withMessage('Search term must be less than 100 characters')
      .trim()
      .escape(),
  ],
  validate,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, sort = 'id', search } = req.query;

      // Mock data - in production, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Eve', email: 'eve@example.com' },
      ];

      let filteredUsers = users;

      // Apply search filter
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply sorting
      filteredUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Apply pagination
      const startIndex = offset;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit,
          offset,
          hasMore: endIndex < filteredUsers.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: 'An error occurred while fetching users.'
      });
    }
  }
);

/**
 * Get a specific user by ID
 * GET /users/:id
 */
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt()
  ],
  validate,
  (req, res) => {
    try {
      const { id } = req.params;

      // Mock data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      const user = users.find(u => u.id === id);

      if (!user) {
        return res.status(404).json({ 
          error: 'Not Found',
          message: `User with ID ${id} not found`
        });
      }

      res.json(user);
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: 'An error occurred while fetching the user.'
      });
    }
  }
);

/**
 * Example: Create a new user (illustrates body validation)
 * POST /users
 */
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s\-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long')
  ],
  validate,
  authLimiter, // Stricter rate limiting for write operations
  (req, res) => {
    try {
      const { name, email } = req.body;

      // In production, would insert into database
      const newUser = {
        id: Date.now(), // Not production-safe, use proper ID generation
        name,
        email
      };

      console.log('User created:', { id: newUser.id, email: newUser.email });

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: 'An error occurred while creating the user.'
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// Handle JSON parsing errors
app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    console.warn('JSON parsing error:', {
      url: req.url,
      ip: req.ip
    });

    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON in request body'
    });
  }
  next(err);
});

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.url
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with context for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  // Determine if we should expose error details
  const isDevelopment = process.env.NODE_ENV === 'development';

  // HTTP status code
  const status = err.status || 500;

  // Prepare response
  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  // Add stack trace only in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

// Only start server if this file is run directly (not required as module)
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Health check: http://localhost:${PORT}/health`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('Server closed. Exiting...');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
}

module.exports = app;

/**
 * Security Tests for app.js
 * Demonstrates testing for common vulnerabilities
 */

const request = require('supertest');
const app = require('./app.improved');

describe('Security Tests', () => {

  describe('Input Validation Tests', () => {

    test('should reject negative limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=-10')
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
      expect(response.body.details).toBeDefined();
    });

    test('should reject limit > 100', async () => {
      const response = await request(app)
        .get('/users?limit=101')
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    test('should reject invalid sort parameter', async () => {
      const response = await request(app)
        .get('/users?sort=malicious_payload')
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    test('should reject non-integer user ID', async () => {
      const response = await request(app)
        .get('/users/abc')
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    test('should reject SQL injection attempt in search', async () => {
      const response = await request(app)
        .get('/users?search=\'; DROP TABLE users;--')
        .expect(200); // Should handle it safely

      // Should not cause errors
      expect(response.body).toHaveProperty('data');
    });

  });

  describe('HTTP Header Tests', () => {

    test('should set security headers', async () => {
