// Security-enhanced application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers (helmet.js)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Strict limit for sensitive endpoints
  message: 'Too many attempts, please try again later.',
});

app.use(limiter);

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ERROR HANDLING
// ============================================================================

// Generic error handler
app.use((err, req, res, next) => {
  // Log the full error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with validation
app.get('/users',
  [
    // Validate query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('fields')
      .optional()
      .matches(/^[a-zA-Z0-9,_]+$/)
      .withMessage('Fields must contain only alphanumeric characters, commas, and underscores'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email', '-id', '-name', '-email'])
      .withMessage('Invalid sort field'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const limit = req.query.limit || users.length;
      const offset = req.query.offset || 0;

      // Apply field filtering (whitelist approach)
      const allowedFields = ['id', 'name', 'email'];
      let filteredUsers = users;

      if (req.query.fields) {
        const requestedFields = req.query.fields.split(',');
        const validFields = requestedFields.filter(f => allowedFields.includes(f));

        if (validFields.length > 0) {
          filteredUsers = users.map(user => {
            const result = {};
            validFields.forEach(field => {
              result[field] = user[field];
            });
            return result;
          });
        }
      }

      // Apply sorting
      if (req.query.sort) {
        const sortField = req.query.sort.startsWith('-') 
          ? req.query.sort.substring(1) 
          : req.query.sort;
        const sortOrder = req.query.sort.startsWith('-') ? -1 : 1;

        if (allowedFields.includes(sortField)) {
          filteredUsers.sort((a, b) => {
            if (a[sortField] < b[sortField]) return -1 * sortOrder;
            if (a[sortField] > b[sortField]) return 1 * sortOrder;
            return 0;
          });
        }
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit,
          offset,
        },
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ error: 'Failed to retrieve users' });
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown();
});

module.exports = app;

// ============================================================
// SECURITY PATTERNS & BEST PRACTICES FOR EXPRESS.JS
// ============================================================
// Copy and use these patterns in your routes as needed

const { body, query, param, validationResult } = require('express-validator');

// ============================================================
// VALIDATION MIDDLEWARE
// ============================================================

/**
 * Generic validation error handler
 * Use this after validation chains in your routes
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================
// COMMON VALIDATION CHAINS
// ============================================================

/**
 * Validate Email
 */
const validateEmail = () => body('email')
  .trim()
  .isEmail()
  .normalizeEmail()
  .withMessage('Invalid email address');

/**
 * Validate Password
 * Enforcement: Min 8 chars, 1 uppercase, 1 lowercase, 1 number, 1 special char
 */
const validatePassword = () => body('password')
  .isLength({ min: 8 })
  .withMessage('Password must be at least 8 characters')
  .matches(/[A-Z]/)
  .withMessage('Password must contain at least one uppercase letter')
  .matches(/[a-z]/)
  .withMessage('Password must contain at least one lowercase letter')
  .matches(/[0-9]/)
  .withMessage('Password must contain at least one number')
  .matches(/[!@#$%^&*(),.?":{}|<>]/)
  .withMessage('Password must contain at least one special character');

/**
 * Validate Username
 * Allowed: Alphanumeric, underscores, hyphens, 3-30 chars
 */
const validateUsername = () => body('username')
  .trim()
  .isLength({ min: 3, max: 30 })
  .matches(/^[a-zA-Z0-9_-]+$/)
  .withMessage('Username can only contain letters, numbers, underscores, and hyphens');

/**
 * Validate ID Parameter
 */
const validateIdParam = () => param('id')
  .isInt({ min: 1 })
  .withMessage('ID must be a positive integer');

/**
 * Validate UUID Parameter
 */
const validateUUID = (paramName = 'id') => param(paramName)
  .isUUID()
  .withMessage(`${paramName} must be a valid UUID`);

/**
 * Validate Pagination
 */
const validatePagination = () => [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
];

/**
 * Validate Sort Parameter (Whitelist Approach)
 */
const validateSort = (allowedFields) => query('sort')
  .optional()
  .custom((value) => {
    const field = value.startsWith('-') ? value.substring(1) : value;
    if (!allowedFields.includes(field)) {
      throw new Error(`Invalid sort field. Allowed: ${allowedFields.join(', ')}`);
    }
    return true;
  });

/**
 * Sanitize String Input
 * Prevents XSS and injection
 */
const sanitizeString = (fieldName) => body(fieldName)
  .trim()
  .escape()
  .notEmpty()
  .withMessage(`${fieldName} is required`);

/**
 * Validate JSON Field
 */
const validateJSON = (fieldName) => body(fieldName)
  .custom((value) => {
    try {
      JSON.parse(value);
      return true;
    } catch (e) {
      throw new Error(`${fieldName} must be valid JSON`);
    }
  });

/**
 * Validate Date Range
 */
const validateDateRange = () => [
  query('startDate')
    .optional()
    .isISO8601()
    .withMessage('Start date must be a valid ISO 8601 date'),
  query('endDate')
    .optional()
    .isISO8601()
    .withMessage('End date must be a valid ISO 8601 date'),
];

// ============================================================
// SECURITY MIDDLEWARE PATTERNS
// ============================================================

/**
 * Sanitize HTML content to prevent XSS
 */
const xssProtection = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      return obj
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;');
    }
    if (Array.isArray(obj)) {
      return obj.map(sanitize);
    }
    if (obj && typeof obj === 'object') {
      const sanitized = {};
      for (const key in obj) {
        sanitized[key] = sanitize(obj[key]);
      }
      return sanitized;
    }
    return obj;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);
  if (req.params) req.params = sanitize(req.params);
  next();
};

/**
 * Prevent NoSQL Injection by checking for $ operators
 */
const noSQLInjectionProtection = (req, res, next) => {
  const checkForMongoOperators = (obj) => {
    if (typeof obj === 'object' && obj !== null) {
      for (const key in obj) {
        if (key.startsWith('$')) {
          throw new Error('Invalid input detected');
        }
        checkForMongoOperators(obj[key]);
      }
    }
  };

  try {
    if (req.body) checkForMongoOperators(req.body);
    if (req.query) checkForMongoOperators(req.query);
    if (req.params) checkForMongoOperators(req.params);
    next();
  } catch (error) {
    return res.status(400).json({ error: 'Invalid input detected' });
  }
};

/**
 * Content-Type validation
 * Ensures only JSON is accepted for JSON endpoints
 */
const validateContentType = (req, res, next) => {
  if (req.method !== 'GET' && !req.is('application/json')) {
    return res.status(415).json({
      error: 'Unsupported Media Type',
      message: 'Content-Type must be application/json',
    });
  }
  next();
};

/**
 * IP whitelist middleware
 */
const createIPWhitelist = (allowedIPs) => (req, res, next) => {
  const clientIP = req.ip || req.connection.remoteAddress;

  if (!allowedIPs.includes(clientIP)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Your IP is not authorized to access this resource',
    });
  }
  next();
};

/**
 * Request timeout middleware
 */
const requestTimeout = (ms) => (req, res, next) => {
  const timeout = setTimeout(() => {
    if (!res.headersSent) {
      res.status(408).json({ error: 'Request timeout' });
    }
    req.socket.destroy();
  }, ms);

  res.on('finish', () => clearTimeout(timeout));
  res.on('close', () => clearTimeout(timeout));
  next();
};

// ============================================================
// ERROR HANDLING PATTERNS
// ============================================================

/**
 * Async route wrapper to catch errors
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Class-based HTTP errors
 */
class HTTPError extends Error {
  constructor(statusCode, message, details = null) {
    super(message);
    this.statusCode = statusCode;
    this.details = details;
    this.name = 'HTTPError';
  }
}

class BadRequestError extends HTTPError {
  constructor(message = 'Bad Request', details = null) {
    super(400, message, details);
  }
}

class UnauthorizedError extends HTTPError {
  constructor(message = 'Unauthorized', details = null) {
    super(401, message, details);
  }
}

class ForbiddenError extends HTTPError {
  constructor(message = 'Forbidden', details = null) {
    super(403, message, details);
  }
}

class NotFoundError extends HTTPError {
  constructor(message = 'Not Found', details = null) {
    super(404, message, details);
  }
}

class ConflictError extends HTTPError {
  constructor(message = 'Conflict', details = null) {
    super(409, message, details);
  }
}

// ============================================================
// USAGE EXAMPLES
// ============================================================

/*
// Example 1: User Registration Route
app.post('/users/register',
  [
    validateUsername(),
    validateEmail(),
