// Secure Express application with comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Apply security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Configure JSON body parser with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true // Only accept objects and arrays
}));

// Configure URL-encoded parser
app.use(express.urlencoded({ 
  extended: false, // More secure query string parser
  limit: '10kb' 
}));

// ============================================================================
// RATE LIMITING
// ============================================================================

// General API rate limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 900
  },
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

// Stricter rate limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

// Apply rate limiting to all routes
app.use('/api/', apiLimiter);

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

// Validation error handler middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation attempts for security monitoring
    console.warn(`Validation failed: ${JSON.stringify(errors.array())}`);

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitization middleware to prevent NoSQL injection
const sanitizeObjectId = (req, res, next) => {
  const { id } = req.params;
  if (id && !/^[a-fA-F0-9]{24}$/.test(id)) {
    return res.status(400).json({
      error: 'Invalid ID format'
    });
  }
  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for monitoring (exclude stack trace in production)
  console.error('Error:', {
    message: err.message,
    status: err.status,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.status ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// API ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Users endpoint with query parameter validation
app.get('/users', 
  // Validate query parameters
  [
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('email')
      .optional()
      .isEmail()
      .withMessage('Email must be a valid email address')
      .normalizeEmail(),
    query('name')
      .optional()
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape() // Prevent XSS
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { id, limit, offset, email, name } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters based on validated parameters
      let filteredUsers = users;

      if (id) {
        filteredUsers = filteredUsers.filter(user => user.id === id);
      }

      if (email) {
        filteredUsers = filteredUsers.filter(user => 
          user.email.toLowerCase() === email.toLowerCase()
        );
      }

      if (name) {
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(name.toLowerCase())
        );
      }

      // Apply pagination
      const startIndex = offset || 0;
      const endIndex = limit ? startIndex + limit : undefined;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: limit || filteredUsers.length,
          offset: startIndex
        }
      });

    } catch (error) {
      next(error);
    }
  }
);

// Example secured POST endpoint (for demonstration)
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Email must be valid')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Process the validated data
      res.status(201).json({
        message: 'User created successfully',
        data: { name, email, age }
      });

    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown();
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

