const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets security-related HTTP headers
app.use(express.json({ limit: '10kb' })); // Body size limit to prevent DoS

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array(),
    });
  }
  next();
};

// Logging middleware for security monitoring
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with validation and security
app.get(
  '/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('id').optional().isInt().withMessage('ID must be an integer'),
  ],
  validateRequest,
  async (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Validate and sanitize query parameters
      const limit = parseInt(req.query.limit) || users.length;
      const offset = parseInt(req.query.offset) || 0;
      const requestedId = req.query.id;

      // Filter by ID if provided
      let filteredUsers = requestedId 
        ? users.filter(u => u.id === parseInt(requestedId))
        : users;

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      // Sanitize output (remove sensitive fields if any)
      const sanitizedUsers = paginatedUsers.map(({ id, name, email }) => ({
        id,
        name,
        email: email.includes('@') ? email : '***@***.***' // Basic email validation
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length,
          hasMore: offset + limit < filteredUsers.length
        }
      });

    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        error: 'An error occurred while fetching users',
        requestId: req.headers['x-request-id'] || 'unknown'
      });
    }
  }
);

// User by ID endpoint with parameter validation
app.get(
  '/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
  ],
  validateRequest,
  async (req, res) => {
    try {
      const userId = parseInt(req.params.id);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json({ data: user });

    } catch (error) {
      console.error('User fetch error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.headers['x-request-id'] || 'unknown',
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

