const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ============ Security Middleware ============

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later' }
});
app.use(limiter);

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============ Validation Helper ============

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// ============ Security Logging ============

const logSecurityEvent = (event, details) => {
  console.error(`[SECURITY] ${event}:`, JSON.stringify(details));
  // In production, send to SIEM or security monitoring service
};

// ============ Routes ============

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users',
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('fields').optional().matches(/^[a-zA-Z,]+$/).withMessage('Invalid field names'),
  validateRequest,
  (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const requestedFields = req.query.fields ? req.query.fields.split(',') : null;

      // Base user data (without sensitive fields)
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Filter fields if specified
      let users = allUsers;
      if (requestedFields) {
        const allowedFields = ['id', 'name'];
        const validFields = requestedFields.filter(f => allowedFields.includes(f));
        users = allUsers.map(user => {
          const filtered = {};
          validFields.forEach(field => {
            if (user[field] !== undefined) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      res.json({
        data: users,
        pagination: {
          page,
          limit,
          total: allUsers.length,
          totalPages: Math.ceil(allUsers.length / limit)
        }
      });
    } catch (error) {
      logSecurityEvent('users_endpoint_error', { error: error.message });
      throw error;
    }
  }
);

// Example of a POST route with input validation
app.post('/users',
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
  validateRequest,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // In a real app, validate email uniqueness, hash passwords, etc.

      res.status(201).json({
        message: 'User created successfully',
        data: {
          id: Date.now(), // In production, use proper ID generation
          name,
          // Don't return email in response for privacy
        }
      });
    } catch (error) {
      logSecurityEvent('user_creation_error', { error: error.message });
      throw error;
    }
  }
);

// ============ Error Handlers ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);

  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log security-related errors
  if (err.status === 400 || err.status === 401 || err.status === 403) {
    logSecurityEvent('security_error', {
      status: err.status,
      path: req.path,
      ip: req.ip
    });
  }

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============ Server Startup ============

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  });
}

module.exports = app;

