    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt()
  ],
  validateRequest,
  async (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = users;
      const { id, name, email, limit, offset } = req.query;

      // Filter by ID
      if (id) {
        filteredUsers = filteredUsers.filter(user => user.id === id);
      }

      // Filter by name (partial match, case-insensitive)
      if (name) {
        const searchName = name.toLowerCase();
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(searchName)
        );
      }

      // Filter by email (exact match)
      if (email) {
        filteredUsers = filteredUsers.filter(user => 
          user.email.toLowerCase() === email.toLowerCase()
        );
      }

      // Apply pagination
      const startIndex = offset || 0;
      const endIndex = limit ? startIndex + limit : filteredUsers.length;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      const response = {
        data: paginatedUsers,
        meta: {
          count: paginatedUsers.length,
          total: filteredUsers.length,
          ...(offset && { offset: startIndex }),
          ...(limit && { limit })
        }
      };

      res.json(response);
    } catch (error) {
      next(error); // Pass to global error handler
    }
  }
);

