const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP security headers
app.use(express.json({ limit: '10kb' })); // Parse JSON with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Parse URL-encoded data with size limit

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive routes
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10, // Limit each IP to 10 requests per windowMs
  message: {
    error: 'Too many requests to this endpoint, please try again later.'
  }
});

// Middleware to validate incoming requests
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Middleware to handle async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Custom input sanitization
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potentially dangerous characters
  return input
    .replace(/[<>]/g, '') // Remove < and > to prevent XSS
    .trim()
    .slice(0, 1000); // Limit length
};

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development' 
    ? err.message 
    : 'An unexpected error occurred';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
  });
});

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
}));

// Users endpoint with validation
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .isLength({ max: 100 })
      .withMessage('Search term must be less than 100 characters')
      .customSanitizer((value) => sanitizeInput(value)),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, search } = req.query;

    // Mock user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Filter users if search term provided
    let filteredUsers = allUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length,
      },
    });
  })
);

// User creation endpoint with validation (example of POST validation)
app.post(
  '/users',
  strictLimiter, // Stricter rate limiting for writes
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters')
      .customSanitizer(sanitizeInput),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Must be a valid email address')
      .isLength({ max: 255 })
      .withMessage('Email must be less than 255 characters'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In production, you would save to a database here
    // and handle potential database errors

    const newUser = {
      id: Date.now(), // Simple ID generation (use UUIDs in production)
      name: sanitizeInput(name),
      email: email.toLowerCase(),
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  })
);

// Example of parameterized route with validation
app.get(
  '/users/:id',
  [
    // Validate that id is a positive integer
  ],
  asyncHandler(async (req, res, next) => {
    const userId = parseInt(req.params.id, 10);

    // Validate the parameter
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID must be a positive integer',
      });
    }

    // Mock user lookup
    const user = {
      id: 1,
      name: 'Alice',
      email: 'alice@example.com',
    };

    if (!user || user.id !== userId) {
      return res.status(404).json({
        error: 'User not found',
        userId,
      });
    }

    res.json({ data: user });
  })
);

module.exports = app;

// Only start server if this file is run directly (not imported)
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

