app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes or specific routes
app.use('/api/', limiter);

// Custom error handling middleware
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Health check endpoint with validation
app.get('/health', 
  asyncHandler(async (req, res) => {
    try {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    } catch (error) {
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'An unexpected error occurred'
      });
    }
  })
);

// Users endpoint with query parameter validation
app.get('/users',
  [
    // Validate query parameters if any
    query('id').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('email').optional().isEmail().normalizeEmail(),
  ],
  handleValidationErrors,
