    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by ID if provided
      let filteredUsers = users;
      if (req.query.id) {
        filteredUsers = users.filter(user => user.id === req.query.id);
      }

      // Filter by email if provided
      if (req.query.email) {
        filteredUsers = filteredUsers.filter(user => 
          user.email.toLowerCase() === req.query.email.toLowerCase()
        );
      }

      // Apply limit if provided
      if (req.query.limit) {
        filteredUsers = filteredUsers.slice(0, req.query.limit);
      }

      // Return 404 if no users found after filtering
      if (filteredUsers.length === 0) {
        return res.status(404).json({ 
          error: 'Not found',
          message: 'No users matching the criteria'
        });
      }

      res.json(filteredUsers);
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'An error occurred while fetching users'
      });
    }
  })
);

