const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(morgan('combined')); // Request logging

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation errors for security monitoring
    console.warn('Validation errors:', {
      ip: req.ip,
      path: req.path,
      errors: errors.array(),
      timestamp: new Date().toISOString()
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Centralized error handler
const errorHandler = (err, req, res, next) => {
  // Log error detailed information
  console.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send appropriate error response
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message,
    statusCode,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  console.warn('404 Not Found:', {
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  res.status(404).json({
    error: 'Resource not found',
    path: req.path
  });
};

// Health check endpoint with validation
app.get('/health', 
  query('format').optional().isIn(['json', 'text']),
  validateRequest,
  (req, res) => {
    try {
      const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (req.query.format === 'text') {
        res.set('Content-Type', 'text/plain');
        res.send(`Status: ${healthData.status}, Time: ${healthData.timestamp}`);
      } else {
        res.json(healthData);
      }
    } catch (error) {
      throw error;
    }
  }
);

// Users endpoint with validation
app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email'),
  query('fields')
    .optional()
    .custom((value) => {
      // Validate comma-separated field names
      const allowedFields = ['id', 'name', 'email'];
      const fields = value.split(',').map(f => f.trim());
      const invalidFields = fields.filter(f => !allowedFields.includes(f));
      if (invalidFields.length > 0) {
        throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
      }
      return true;
    }),
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply field filtering
      let result = users;
      if (req.query.fields) {
        const requestedFields = req.query.fields.split(',').map(f => f.trim());
        result = users.map(user => {
          const filtered = {};
          requestedFields.forEach(field => {
            if (user.hasOwnProperty(field)) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      // Apply sorting
      if (req.query.sort) {
        const sortField = req.query.sort;
        result = [...result].sort((a, b) => {
          if (a[sortField] < b[sortField]) return -1;
          if (a[sortField] > b[sortField]) return 1;
          return 0;
        });
      }

      // Apply limit
      if (req.query.limit) {
        result = result.slice(0, parseInt(req.query.limit));
      }

      res.json(result);
    } catch (error) {
      throw error;
    }
  }
);

// Example POST endpoint demonstrating body validation
app.post('/users',
  express.json(),
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  validateRequest,
  (req, res) => {
    try {
      // In a real app, you'd save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation (use UUID or similar in production)
        name: req.body.name,
        email: req.body.email
      };

      console.info('User created:', {
        id: newUser.id,
        email: newUser.email,
        ip: req.ip,
        timestamp: new Date().toISOString()
      });

      res.status(201).json(newUser);
    } catch (error) {
      throw error;
    }
  }
);

// Middleware to handle 404s - must be after all routes
app.use(notFoundHandler);

// Error handling middleware - must be last
app.use(errorHandler);

const PORT = process.env.PORT || 3000;

// Only start server if not imported (for testing)
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

# Security Review and Improvements for app.js

## Executive Summary

The original `app.js` file has several security vulnerabilities and lacks essential security controls. The improved version (`app.improved.js`) implements defense-in-depth security practices following OWASP guidelines.

---

## Vulnerabilities Identified

### 1. ❌ Missing Input Validation
**Severity: HIGH**

**Issue:** User inputs (query parameters, headers, body) are never validated.

**Risks:**
- Injection attacks
- Business logic abuse
- Data corruption
- Information disclosure

**Example Attack:**
```bash
# Unvalidated input could cause unexpected behavior
GET /users?limit=9999999999999
GET /users?sort=DROP+TABLE+users--
```

---

### 2. ❌ No Error Handling
**Severity: MEDIUM**

**Issue:** No centralized error handling mechanism.

**Risks:**
- Stack traces exposed to users (information disclosure)
- Inconsistent error responses
- Poor debugging experience
- Potential application crashes

---

### 3. ❌ Missing Rate Limiting
**Severity: HIGH**

**Issue:** No protection against brute force or DoS attacks.

**Risks:**
- API abuse
- Resource exhaustion
- Brute force on endpoints
- Denial of Service

---

### 4. ❌ Missing Security Headers
**Severity: MEDIUM**

**Issue:** No HTTP security headers configured.

**Missing Headers:**
- `X-Content-Type-Options`
- `X-Frame-Options`
- `X-XSS-Protection`
- `Strict-Transport-Security`
- `Content-Security-Policy`

**Risks:**
- Clickjacking attacks
- XSS exploits
- MIME type sniffing attacks
- Man-in-the-middle attacks

---

### 5. ❌ No Request Size Limits
**Severity: MEDIUM**

**Issue:** No limits on request body size.

**Risks:**
- Memory exhaustion attacks
- Server crashes from large payloads
- Slowloris attacks

---

### 6. ❌ No Security Logging
**Severity: MEDIUM**

**Issue:** No logging of security-relevant events.

**Missing Logs:**
- Failed validation attempts
- Rate limit violations
- 404 errors (potential enumeration)
- Application errors

---

### 7. ❌ No Input Sanitization
**Severity: HIGH**

**Issue:** User input is used directly without sanitization.

**Risks:**
- NoSQL/SQL injection
- XSS if data is reflected
- Command injection

---

## Improvements Implemented

### 1. ✅ Security Middleware Using Helmet

```javascript
app.use(helmet());
```

**Benefits:**
- Sets 11 important security headers by default
- Protects against well-known web vulnerabilities
- Easily configurable

---

### 2. ✅ Rate Limiting

```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP'
});
app.use(limiter);
```

**Benefits:**
- Prevents brute force attacks
- Protects against DoS
- Configurable per-route

---

### 3. ✅ Input Validation with express-validator

```javascript
query('limit')
  .optional()
  .isInt({ min: 1, max: 100 })
  .withMessage('Limit must be between 1 and 100')
```

**Benefits:**
- Type checking
- Range validation
- Custom validation rules
- Clear error messages

---

### 4. ✅ Centralized Error Handling

```javascript
const errorHandler = (err, req, res, next) => {
  // Log error details
  console.error('Error occurred:', {
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    timestamp: new Date().toISOString()
  });

  // Send sanitized response
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message
  });
};
```

**Benefits:**
- Consistent error responses
- No stack traces in production
- Comprehensive logging
- Prevents information disclosure

---

### 5. ✅ Request Size Limits

```javascript
app.use(express.json({ limit: '10kb' }));
```

**Benefits:**
- Prevents memory exhaustion
- Limits attack surface
- Configurable per content type

---

### 6. ✅ Security Logging with Morgan

```javascript
app.use(morgan('combined'));
```

**Benefits:**
- Audit trail
- Incident response support
- Attack detection
- Compliance requirements

---

### 7. ✅ Request Validation Middleware

```javascript
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    console.warn('Validation errors:', {
      ip: req.ip,
      path: req.path,
      errors: errors.array()
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};
```

**Benefits:**
- Reusable validation logic
- Consistent validation responses
- Security event logging
- Type safety

---

### 8. ✅ Input Sanitization

```javascript
body('name')
  .trim()                          // Remove whitespace
  .matches(/^[a-zA-Z\s'-]+$/)      // Validate characters
  .isLength({ min: 2, max: 100 })  // Validate length
body('email')
  .trim()
  .normalizeEmail()                // Normalize email format
  .isEmail()
```

**Benefits:**
- Prevents injection attacks
- Normalizes input data
- Removes dangerous characters
- Validates data format

